from pathlib import Path
from html import escape
import math
import json
import re

OUT=Path(__file__).parent
source_catalog=json.loads((OUT/'documentation-sources.json').read_text())
sources=source_catalog['sources']
chapters=[]
def source_links(source):
    return ' · '.join(ref(item['url'],item['label']) for item in source['links'])
def source_bibliography():
    sections=[]
    for kind in dict.fromkeys(source['kind'] for source in sources):
        entries=[]
        for source in sources:
            if source['kind']!=kind:continue
            topics=' · '.join(link(key,next(c[1] for c in chapters if c[0]==key)) for key in source['topics'])
            entries.append('<li><strong>'+escape(source['title'])+'</strong><br>'+escape(source['author'])+' — '+escape(source['year'])+'.<br>'+escape(source['used_for'])+'<br>'+source_links(source)+'<br>Used in: '+topics+'</li>')
        sections.append('<h2>'+escape(kind)+'</h2><ul>'+''.join(entries)+'</ul>')
    intro='<h2>Source bibliography</h2><p>This bibliography identifies the sources cited or cross-checked for the guide. Each entry states its role: algorithm definition, dataset lineage, implementation reference, platform API or documentation design. OKLab’s original publication is an author technical article; the Machado and Munsell entries are journal papers. Historical dataset citations do not imply that the app reconstructed the original experiments. Bibliographic identities and official resource links were checked on '+source_catalog['checked_on']+'. Publisher full-text access and some institutional pages may vary.</p>'
    own='<h2>Color Atlas implementation and original material</h2><p>The app’s coordinate scaling, relative-chroma slider, gamut interaction rules, harmony generation, importance-layer mapping, encoded-byte reference mapping, bloom parameters and attention overlay are documented from the current app source. These are product choices and heuristics, without a claim of a peer-reviewed paper validating the combined behavior.</p><p>The guide diagrams and saliency study are original illustrations of app calculations and a contextual color exercise. The explosion image is a bundled project reference asset; external authorship has not been verified. See '+link('grayscale-mapping','the reference-image chapter')+'. Presets are authored or approximate design references, without an inferred official or measured provenance.</p>'
    return intro+''.join(sections)+own

def topic_sources(key):
    selected=[source for source in sources if key in source['topics']]
    if not selected:return ''
    return '<h2>Sources for this topic</h2><ul>'+''.join('<li>'+link('glossary',escape(source['title']))+'</li>' for source in selected)+'</ul>'

def topic(key,title,lead,body,group):
    if key=='glossary':
        body=re.sub(r'<h2>Primary technical references</h2>[\s\S]*?(?=<h2>Guide design</h2>)',lambda _:source_bibliography(),body,count=1)
    else:
        body+=topic_sources(key)
    chapters.append((key,title,group,f'<article id="doc-{key}" class="atlas-docs-article" data-doc-topic="{key}" hidden><div class="atlas-docs-eyebrow">Color Atlas / {escape(group)}</div><h1 tabindex="-1">{escape(title)}</h1><p class="doc-lead">{lead}</p>{body}</article>'))
def table(headers,rows):
    return '<div class="atlas-docs-table"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def ref(url,label):
    return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{label}</a>'
def link(key,label):
    return f'<a href="#doc-{key}" data-doc-link="{key}">{label}</a>'
def svg(title,body,height=220):
    return f'<svg viewBox="0 0 720 {height}" role="img" aria-label="{escape(title,quote=True)}"><title>{escape(title)}</title><rect width="720" height="{height}" fill="#0e1621"/><g font-family="system-ui,sans-serif" fill="#c9d9ed" font-size="13">{body}</g></svg>'
def fig(title,body,caption,height=220):
    return '<figure>'+svg(title,body,height)+'<figcaption>'+caption+'</figcaption></figure>'
def txt(x,y,text,**attrs):
    styles=[]
    if 'fill' in attrs:styles.append('fill:'+attrs.pop('fill'))
    if 'font_size' in attrs:styles.append('font-size:'+str(attrs.pop('font_size'))+'px')
    if styles:attrs['style']=';'.join(styles)
    return '<text x="%s" y="%s" %s>%s</text>'%(x,y,' '.join(f'{k.replace("_","-")}="{v}"' for k,v in attrs.items()),escape(text))
def decode(x):return x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4
def encode(x):return 12.92*x if x<=.0031308 else 1.055*x**(1/2.4)-.055
def linear(l,a,b):
    ll=(l+.3963377774*a+.2158037573*b)**3;mm=(l-.1055613458*a-.0638541728*b)**3;ss=(l-.0894841775*a-1.291485548*b)**3
    return [4.0767416621*ll-3.3077115913*mm+.2309699292*ss,-1.2684380046*ll+2.6097574011*mm-.3413193965*ss,-.0041960863*ll-.7034186147*mm+1.707614701*ss]
def lab(hex):
    r,g,b=[decode(int(hex[i:i+2],16)/255) for i in (1,3,5)]
    l=(.4122214708*r+.5363325363*g+.0514459929*b)**(1/3);m=(.2119034982*r+.6806995451*g+.1073969566*b)**(1/3);s=(.0883024619*r+.2817188376*g+.6299787005*b)**(1/3)
    return [.2104542553*l+.793617785*m-.0040720468*s,1.9779984951*l-2.428592205*m+.4505937099*s,.0259040371*l+.7827717662*m-.808675766*s]
def hexlin(rgb):return '#'+''.join(f'{math.floor(255*encode(max(0,min(1,x)))+.5):02x}' for x in rgb)
def ramp(colors,x,y,width=560,height=28):
    number=lambda value:f'{value:.2f}'.rstrip('0').rstrip('.')
    runs=[]
    for i,c in enumerate(colors):
        if runs and runs[-1][2]==c:runs[-1][1]=i+1
        else:runs.append([i,i+1,c])
    return '<g shape-rendering="crispEdges">'+''.join(f'<path d="M{number(x+a*width/len(colors))} {y}h{number((b-a)*width/len(colors)+.2)}v{height}h-{number((b-a)*width/len(colors)+.2)}z" fill="{c}"/>' for a,b,c in runs)+'</g>'

pipeline=''
for i,(a,b) in enumerate([('01  Author','OKLab / HEX'),('02  Arrange','Color + alpha keys'),('03  Map','Grayscale lookup'),('04  Export','RGBA texture')]):
    x=24+i*174
    pipeline+=f'<rect x="{x}" y="58" width="150" height="88" rx="6" fill="#192738" stroke="#3c526c"/>'+txt(x+14,88,a)+txt(x+14,116,b,font_size=11,fill='#99b4d1')
    if i<3:pipeline+=f'<path d="M{x+154} 102h16m-6-6 6 6-6 6" fill="none" stroke="#99b4d1"/>'
pipeline+=txt(24,184,'Preview effects inspect the result. PNG exports the gradient itself.',font_size=12)
workflow=fig('Color Atlas workflow from color authoring to texture export',pipeline,'The editor turns a scalar signal into color. The preview is a demonstration of that lookup, not a fluid simulation.')

topic('overview','Welcome to Color Atlas','Color Atlas designs color ramps, previews effects and exports textures for game engines. Start with a preset, edit colors and check the preview.', '<h2>Opening the app</h2><p>The splash uses the explosion, version, dark Perlin patches, white Ca badge and header logo. Loading uses 3–6 phrases, increasing random percentages and 220–420 ms steps, ending at 100%. Explosion framing: 2.3× zoom, 8% left/5% down, clipped. Progress is decorative.</p><p>At the final step the editor starts behind the splash. Images, saved layers and fonts settle before two layout frames reveal it. Readiness times out after 1.5 seconds. Skip/Escape checks sooner; reduced motion bypasses the splash. Dark boot CSS.</p><p>SVG Perlin noise uses 65 OKLab-interpolated colors (L=0.07–0.28, chroma ≤0.049). Dismissal stops animation; presets are preserved.</p><p>Below Preview, bloom uses a short centered slider, separate from panel dividers.</p><h2>What the app does</h2>'+workflow+'<p>The VFX workspace combines color authoring, gradients and image layers. Each image retains two importance ramps.</p><h2>Technical scope</h2><p>Keys use 8-bit sRGB HEX. Smooth interpolates in OKLab; alpha keys define opacity. Preview maps grayscale through the ramps; PNG export samples RGBA.</p><p>No fluid simulation, display measurement, spectral recovery, HDR export or automatic native engine assets.</p><div class="doc-note">Formulas distinguish color-space definitions from app scaling, gamut fitting and preview heuristics.</div><p>Continue with '+link('quick-start','Quick start')+' or '+link('color-spaces','Color spaces and units')+'.</p>','Start here')

topic('quick-start','Quick start','Choose a library preset, select a color key, and move its color in the wheel. The reference effect updates as you work. Export a PNG when the ramp gives you the result you want.', '<h2>Build your first ramp</h2><ol><li>After the brief splash, the app opens in the VFX gradient editor. The editor prepares behind the splash before it becomes visible. Skip or Escape skips the remaining decorative steps; image and layout readiness still runs before revealing the workspace.</li><li>Search the palette library and select a preset. It replaces the active importance layer.</li><li>Press a color key in the list or below the gradient. Change lightness, the two color axes, saturation or HEX.</li><li>Click or drag inside the color wheel to author the selected color immediately.</li><li>Drag keys along the gradient, or use Position for precise placement. Switch Smooth to Bands if you want discrete steps.</li><li>Select a row in Layers to edit that image’s active Gradient Map. Saved Preview presets retain both internal importance ramps and their mapping settings.</li><li>Open Export PNG. Choose PNG, Unity C# or Unreal JSON, select layers and Smooth interpolation, then download the texture or copy the data. PNG also offers dimensions and a file name.</li></ol><h2>Technical detail</h2><p>A key position is a normalized scalar <code>t ∈ [0, 1]</code>, displayed as a percentage. In a shader, that scalar could be particle age, a mask or another normalized quantity. It is a lookup coordinate, not a physical temperature. PNG contains the gradient, not the explosion image or preview filters.</p><p>Read '+link('interpolation','Gradient keys and interpolation')+' and '+link('png-export','PNG export')+' before integrating a texture.</p>','Start here')

topic('interface','Workspace and controls','Authoring Colors is on the left and keys and the wheel are in the middle. Gradient Map spans those two columns. Preview extends to the bottom on the right, with its image-layer stack below the fitted square image.', '<h2>Controls at a glance</h2>'+table(['Area','Action','Result'],[['Library','Search, open folders, select a preset or saved palette, toggle its star','Built-ins affect the active layer; saved snapshots load their chosen scope. Stars manage favorites.'],['Color authoring','Sliders, HEX input + Apply, color wheel','Ramp updates during drags; L pulses above Black–White (unless reduced motion).'],['3D volume','Drag the selection circle; drag elsewhere; middle drag; wheel','Click a node to select; drag the selected circle to edit color; rotate; pan; zoom. Shift-drag rotates even on the marker. During color dragging, points at other lightness levels, other key markers and the dashed path dim; release or cancellation restores them.'],['Color wheel','Left press / drag; middle drag; mouse wheel','Pick / adjust immediately; pan; zoom. Reset view restores the wheel camera.'],['Keys','Select, +, −','Edit points; − or Delete asks before removal.'],['Gradient','Drag a color marker; click empty ramp space','Clicks use SVG coordinates; dragging keeps the grab offset.'],['Position','Adjust the slider on the same row as GRADIENT MAP, after the editing controls','Set the selected color key position.'],['Preview','Drag here marks layers during image dragging; dice, Random, presets, Save, blend/opacity, vision, bloom, eye','Save confirms updates except Default; Random follows dice.'],['Export','Export PNG / Export Preview','PNG exports the ramp; Preview downloads the full 512×512 composite with bloom/vision, without camera framing or attention overlays.']])+'<h2>Undo and Redo</h2><p>Undo/Redo in the Preview header keeps 10 actions; drags count once. Ctrl/Cmd+Z undoes; Ctrl/Cmd+Shift+Z or Ctrl+Y redoes. Text Undo/Delete stay native. All deletions ask for confirmation. New edits clear Redo; reload clears history. Camera/layout and library management are excluded.</p><h2>Layout behavior</h2><p>Desktop: the sidebar handle centers between columns (140–420 px). Outer handles resize the centered app (1100 px to viewport width). Arrows resize; Home/double-click resets. The wheel groups divider, color, then wheel; resizing shares space with keys. Wide/tall layouts have column, Gradient Map and Preview/Layers dividers. Drag or use arrow keys; double-click or Home resets new dividers. Preview fits its slot at startup/reset. Wide/tall Preview starts at 70%; Layers uses 30%. Columns follow 34/23/43%. Sizing reserves control space. Move Preview/Layers down for a larger canvas, up for more layers. Home/double-click resets; compact layers use natural height. Graph and wheel handles remain available. Sizes reset on reload; compact views hide handles. Wheel: 200 px; drag up to enlarge it, keeping 84 px for keys. Reload resets it. Export PNG is right-aligned on the same toolbar row as GRADIENT MAP, Save palette and Position. A subtle 1 px chromatic outline groups Gradient Map, using shared OKLab accents at reduced opacity. This cue leaves colors and exports unchanged. VFX opens by default. System, Engine, importance and Preview mapping controls are hidden; saved settings remain compatible. Choose PNG, Unity C# or Unreal JSON in Export. Rotation uses sRGB switch styling; Layers: 8 px gaps, 20 px top padding. Wheel labels use muted gray; Green/Red sit farther out. COLOR WHEEL centers in its 24px row; Reset view sits right. Compact views wrap the toolbar and scroll.</p><p>The browser edition saves Preview presets and images in IndexedDB, and palettes/settings in localStorage. No Data connection is needed. External links need internet. Slider markers are white. Saturation shows one live value. Reading preserves your work with OKLab highlights. Preview hides save/restore confirmations; errors remain. Tab: Color Atlas. Footer: Created by Raff Ribeiro. Save palette stores the selected ramp. 3D/key-list/Gradient Map numbers match: 1 is the high end; ties keep list order. Muted numbers use fixed offsets and may overlap on rotation. The selected number stays near its circle with stronger contrast. Click nodes to select. The selected circle wins hit tests; rotate to reveal overlaps. Drag unselected nodes to rotate; the selected circle edits color. Other numbers and markers dim while dragging color. Selection scrolls the key list only; color edits keep scrolling.</p>'+OUT.joinpath('clipboard-documentation.html').read_text()+OUT.joinpath('user-palettes-documentation.html').read_text(),'Start here')

# sRGB curve illustration: horizontal encoded value, vertical linear light.
curve='<path d="M70 30V210H665" fill="none" stroke="#536880"/>'
curve+='<path d="M70 210L665 30" stroke="#50617a" fill="none" stroke-dasharray="5 5"/>'
curve+='<path d="'+ ' '.join(('M' if i==0 else 'L')+f'{70+595*i/100:.2f} {210-180*decode(i/100):.2f}' for i in range(101))+'" stroke="#a6c4ff" stroke-width="3" fill="none"/>'
curve+=txt(70,235,'0')+txt(651,235,'1')+txt(30,40,'1')+txt(30,210,'0')+txt(235,258,'Encoded sRGB channel →',font_size=12)+txt(84,48,'Linear-light channel',font_size=12)+txt(375,94,'0.5 encoded ≈ 0.214 linear',font_size=12)
transfer=fig('sRGB decoding curve compared with a straight line',curve,'The dashed line is the identity transform. The blue curve is sRGB decoding; a middle encoded value is not half the linear light.',280)
oklabImplementation='<h2>Why Color Atlas uses OKLab</h2><p>Color Atlas uses OKLab to make artistic color editing and Smooth gradients more predictable. RGB channel values describe display components; they do not directly describe equal perceived color changes. OKLab separates approximate lightness from two opposing color axes, so the wheel can change color direction and chroma while holding lightness fixed.</p><p>Perceptual editing and physical light calculations have different purposes. We use OKLab for authoring and Smooth interpolation, and linear RGB for layer mixing and luminance calculations. OKLab is approximately uniform: it does not guarantee equal visible differences, sufficient contrast or a pleasing palette. It can also pass through low-chroma colors between opposing hues.</p><h2>Standard OKLab and Color Atlas choices</h2><p>The core implementation follows Björn Ottosson’s published OKLab model, introduced in 2020, using the updated 2021 conversion coefficients. Color Atlas does not define a new color space. Converting sRGB to linear RGB, applying the published matrices and cube-root transform, then reversing those steps is the established conversion procedure.</p><pre>Encoded sRGB → decode → linear RGB → OKLab\nEdit or interpolate in OKLab\nOKLab → linear RGB → gamut handling → encode → display sRGB</pre><p>Smooth interpolates the coordinates between keys using q(t) = (1 − t) q₀ + t q₁. This is an established use of OKLab, not a new interpolation algorithm. Alpha is evaluated separately. See <a href="https://bottosson.github.io/posts/oklab/" target="_blank" rel="noopener noreferrer">the original OKLab definition and implementation</a> and <a href="https://www.w3.org/TR/css-color-4/#interpolation-space" target="_blank" rel="noopener noreferrer">the W3C guidance on choosing an interpolation space</a>.</p><div class="atlas-docs-table"><table><thead><tr><th scope="col">Component</th><th scope="col">Established foundation</th><th scope="col">Color Atlas choice</th></tr></thead><tbody><tr><td>Color conversion</td><td>Published OKLab matrices and nonlinear transform.</td><td>Use those equations with stored sRGB HEX keys.</td></tr><tr><td>Control units</td><td>Unscaled L, a and b coordinates.</td><td>Display L × 100, a × 250 and b × 250; undo scaling for conversion and color-distance calculations.</td></tr><tr><td>Color wheel</td><td>A constant-lightness slice of the a/b plane.</td><td>Place Yellow above, Blue below, Green left and Red right, with app-specific picking, zoom and pan.</td></tr><tr><td>Gamut fitting</td><td>Chroma reduction at fixed lightness and hue is a known approach.</td><td>Use radial binary search and the app’s sRGB bounds and interaction rules.</td></tr><tr><td>Saturation control</td><td>OKLab defines chroma; it does not prescribe this slider.</td><td>Measure chroma relative to the app’s editing reference, as explained in Gamut lock and saturation.</td></tr><tr><td>VFX workflow</td><td>Perceptual coordinates support palette editing.</td><td>Combine presets, Random heuristics, importance layers, reference mapping and export options into one tool.</td></tr></tbody></table></div><p>The accurate description is an <strong>OKLab-based gradient authoring tool</strong>. The product-specific work is the control design and integration. Those choices do not establish a new scientific color model, and the app’s harmony or attention heuristics are not properties of OKLab itself.</p>'
topic('color-spaces','Color spaces and units','A color can be described by display RGB values or by coordinates that separate lightness from color direction. Color Atlas uses sRGB for storage and display, and OKLab for perceptual editing and smooth gradients.', oklabImplementation+'<h2>sRGB and linear light</h2><p>HEX channels are encoded sRGB numbers. Calculations such as luminance and layer mixing first decode them to linear light. Alpha is an opacity value and does not use this transfer function.</p><pre>Let c be an encoded sRGB channel in [0, 1].\nlinear(c) = c / 12.92                         if c ≤ 0.04045\n            ((c + 0.055) / 1.055)^2.4         otherwise\n\nLet x be a linear-light channel.\nsRGB(x) = 12.92 x                            if x ≤ 0.0031308\n          1.055 x^(1/2.4) − 0.055            otherwise</pre>'+transfer+'<h2>OKLab and the app’s scale</h2><p>OKLab is a perceptual color space based on D65. Its lightness coordinate is L, with opposing a and b axes. For readable controls, this app rescales the published coordinates:</p><pre>L_UI = 100 L\n a_UI = 250 a\n b_UI = 250 b\n\nPublished OKLab coordinates = (L_UI / 100, a_UI / 250, b_UI / 250)</pre><p>The UI’s lightness and chroma numbers therefore are not CIE L*a*b* units. They are not physical brightness, temperature or exposure. Color distances used by the app are Euclidean distances in the unscaled OKLab coordinates, not CIE ΔE values.</p><p>OKLab is approximately perceptually uniform. Equal distances are useful for editing but do not guarantee equal visible differences across every hue, display, viewing condition or observer.</p><h2>Conversion to display RGB</h2><p>Using unscaled OKLab coordinates, the inverse transform first constructs three intermediate channels and cubes them. A matrix then converts those values to linear sRGB:</p><pre>l′ = L + 0.3963377774 a + 0.2158037573 b\nm′ = L − 0.1055613458 a − 0.0638541728 b\ns′ = L − 0.0894841775 a − 1.2914855480 b\n\nR =  4.0767416621 l′³ − 3.3077115913 m′³ + 0.2309699292 s′³\nG = −1.2684380046 l′³ + 2.6097574011 m′³ − 0.3413193965 s′³\nB = −0.0041960863 l′³ − 0.7034186147 m′³ + 1.7076147010 s′³</pre><p>Display output clamps RGB to [0, 1], applies the sRGB transfer function and rounds each channel to a byte. Out-of-gamut clipping and 8-bit rounding can change the color. The source uses the 2021 OKLab matrices documented in the linked reference.</p><h2>OKLCh</h2><p>OKLCh expresses the same OKLab color using lightness, chroma and hue. The experimental cylindrical workspace is retained in the source but hidden from this app. It is OKLCh, not CIELCh.</p><pre>C_UI = √(a_UI² + b_UI²)\nh = atan2(b_UI, a_UI) · 180 / π   wrapped to [0°, 360°)\na_UI = C_UI cos(h)\nb_UI = C_UI sin(h)</pre><p>At zero chroma, hue has no visible meaning. The app can retain a hue direction so increasing chroma has a predictable direction.</p><h2>Exploring the System views</h2><p>OKLab · 3D volume edits lightness from 0–100 UI and the two color axes from −150 to 150 UI, with a HEX preview and an out-of-sRGB indicator. OKLCh exposes lightness, hue from 0°–359° and chroma from 0–150 UI. Drag its neutral axis to change lightness, or click the active disk to set hue and chroma.</p><p>The OKLCh triad uses h, h + 120° and h + 240° at the same lightness. Chroma can be adjusted independently for each companion color. The solid draws in-gamut slices; an out-of-gamut selected marker and its HEX preview can be clipped. This reference view does not apply the VFX wheel’s automatic radial fitting to every requested coordinate.</p><p>Definitions and conversion matrices: '+ref('https://bottosson.github.io/posts/oklab/','OKLab by Björn Ottosson')+'; '+ref('https://www.w3.org/TR/css-color-4/#color-conversion-code','W3C color conversion reference')+'.</p>','Color science')

topic('munsell','Munsell reference','Munsell describes a color with a hue family, a value from dark to light, and a chroma from neutral to strong color. The bundled data remains a discrete digital reference; its experimental picker is hidden in the current VFX app.', '<h2>Notation and discrete samples</h2><pre>Chromatic notation: Hue Value/Chroma       example: 5R 5/6\nNeutral notation:   N Value/              example: N 5/</pre><p>The retained reference dataset provides 40 hue positions: 2.5, 5, 7.5 and 10 in each of R, YR, Y, GY, G, BG, B, PB, P and RP. Value ranges from 0 to 10. Chroma choices depend on the available samples at that hue and value; the app snaps to the nearest supported choice. Neutrals have chroma zero.</p><h2>Triads and saved palettes</h2><p>The Munsell triad samples hue offsets of 0, 13 and 27 positions on the 40-step wheel. These are approximate thirds, not equal angles in OKLab or exact RGB complements. Value is shared; the other two chromas can be adjusted independently. The hidden experimental picker retains its own color-chip palette state, separate from VFX My palettes. It is not exposed by the current workspace navigation.</p><h2>Renotation data and white-point adaptation</h2><p>The generator converts the Munsell renotation xyY samples defined under Illuminant C into a D65 display reference. It uses Bradford chromatic adaptation before converting XYZ to sRGB. The renotation luminance is scaled by 0.975; this convention is part of preparing the reference data, not an exposure control.</p><pre>Y_normalized = 0.975 × Y_renotation / 100\nIlluminant C: xy = (0.31006, 0.31616)\nD65:          xy = (0.3127, 0.3290)\nXYZ_D65 = BradfordAdapt(XYZ_C, white_C, white_D65)</pre><p>The neutral samples use the generator’s Munsell Value-to-luminance polynomial with the same scale. These adapted, quantized display samples are a digital reference; they do not preserve the spectrum of a physical chip. See the '+ref('https://colour.readthedocs.io/en/master/generated/colour.MUNSELL_COLOURS.html','Colour renotation data notes')+'.</p><h2>Digital limitations</h2><p>The bundled data includes sRGB previews and out-of-gamut flags. An × marks a color whose display preview has been clipped. A HEX code cannot reproduce an out-of-sRGB surface color exactly. Munsell Value is not OKLab L or the RGB average. A screen visualization does not replace physical chips, controlled illumination or instrument measurements.</p><p>Background: '+ref('https://www.rit.edu/science/munsell-color-lab','RIT Munsell Color Science Laboratory')+'.</p>','Color science')

topic('gamut','Gamut lock and saturation','Some color coordinates ask the display for a color it cannot show. Gamut lock reduces the color’s strength until it fits sRGB, helping you edit without losing the selected hue direction.', '<h2>Gamut fitting</h2><p>A candidate is converted from OKLab to linear sRGB. It is in gamut when all three channels lie approximately between zero and one. The fitter keeps lightness fixed and scales both color axes together:</p><pre>q(k) = (L_UI, k a_UI, k b_UI),    0 ≤ k ≤ 1\nFind the largest k such that linearRGB(q(k)) is in [0, 1]³.\nThe app uses 32 binary-search iterations.\nAt L_UI = 0 or 100, the fitted result is neutral.</pre><p>Locked color-axis sliders calculate a valid interval while holding the other axis and lightness fixed. The color wheel always fits its picked colors to sRGB, including when the lock switch is off. Unlocked axis controls can request coordinates outside sRGB, but a stored HEX key still clips and quantizes the resulting display RGB.</p><h2>Meaning of Saturation</h2><p>This control measures radial chroma relative to the app’s reference at the same lightness and hue. The precise interpretation is <strong>relative chroma</strong>. The UI retains the short label Saturation; it is not HSV saturation or a spectral purity measurement.</p><pre>C = √(a_UI² + b_UI²)\nC_ref = chroma after fitting a radius-100 UI point at the same L and hue\n        (100 when unlocked)\nS_UI = clamp(100 C / C_ref, 0, 100)%</pre><p>Adjusting Saturation moves along the current hue direction at fixed lightness. Near black and white, usable chroma collapses and the control can become unavailable. The radius-100 reference is an app-specific editing range, not a universal definition of maximum chroma.</p>','Color science')

# Axis demonstration uses color samples in real OKLab; out-of-gamut candidates fitted radially.
wheel='<circle cx="360" cy="142" r="93" fill="#111c29" stroke="#425975"/>'
for iy in range(-8,9):
    for ix in range(-8,9):
        if ix*ix+iy*iy>64:continue
        a=ix*.028;b=iy*.028;rgb=linear(.7,a,b)
        if min(rgb)<0 or max(rgb)>1:
            lo=0;hi=1
            for _ in range(32):
                k=(lo+hi)/2;v=linear(.7,k*a,k*b)
                if min(v)>=0 and max(v)<=1:lo=k
                else:hi=k
            rgb=linear(.7,lo*a,lo*b)
        wheel+=f'<circle cx="{360+ix*10}" cy="{142-iy*10}" fill="{hexlin(rgb)}"/>'
wheel+=txt(360,26,'YELLOW  +b',text_anchor='middle')+txt(360,266,'BLUE  −b',text_anchor='middle')+txt(218,147,'GREEN  −a',text_anchor='middle')+txt(505,147,'RED  +a',text_anchor='middle')+txt(575,237,'L_UI = 70',text_anchor='middle',font_size=12)
wheelfig=fig('Fixed-lightness OKLab color slice with Yellow above and Blue below','<style>.atlas-doc-wheel circle:not([r]){r:3.3px}</style>'+wheel,'Illustrated at L_UI = 70 using the app’s OKLab conversion and radial sRGB fitting. Color and available chroma change with lightness.',285).replace('<svg ', '<svg class="atlas-doc-wheel" ',1)
topic('volume-wheel','3D volume and color wheel','The 3D view shows display gamut; the wheel edits hue and chroma at fixed lightness. Muted gray labels mark yellow above, blue below, green left and red right.', '<h2>Fixed-lightness slice</h2>'+wheelfig+'<p>The wheel uses the selected key’s lightness. Moving horizontally changes a; moving vertically changes b with the screen’s y axis inverted. The neutral center has zero chroma. The hue ring and dot colors depend on the current lightness; this is not a fixed HSV wheel.</p><pre>a_UI = (x − 110) / 0.55\nb_UI = −(y − 91) / 0.55\nPick disk radius = 50 SVG units\nSelected marker radius from center = min(50, 0.55 C_UI)</pre><p>Pointer positions are first transformed from the screen into the wheel’s SVG coordinates, so zoom and pan do not change the selected color. Left press changes the color immediately; dragging holds lightness fixed and batches updates with animation frames. Gamut fitting follows the method in '+link('gamut','Gamut lock and saturation')+'.</p><h2>Live 3D color editing</h2><p>During a selection-circle drag, other L points, nonselected key markers and the dashed path dim to 18% of their usual opacity. Release or pointer cancellation restores them; the active slice stays clear.</p><p>Grab the selection circle and drag to edit color and preview live. Pressing without moving does not change color; the grab offset is preserved. Lightness and camera stay fixed; alpha, key position and the other layer are preserved. Moves update once per frame; release or cancellation flushes the pending position and saves once.</p><p>A left drag starting anywhere outside the circle rotates, even on the lightness slice at high zoom. Shift-drag always rotates; middle drag pans; the wheel zooms. Out-of-gamut colors are fitted at the same lightness.</p><h2>Sampling and camera</h2><p>729 sRGB samples illustrate OKLab gamut, not measured spectra. Startup and Reset view use yaw 3.55 rad, pitch −0.25 rad, zoom 1 and centered pan. Orthographic projection uses <code>(a_UI, 1.6(L_UI − 50), b_UI)</code> with yaw, pitch, pan and zoom.</p><p>Wheel slices are cached at 0.5 lightness intervals. Zoom increases sampling density; dim dots can mark out-of-gamut requests. Its view zoom spans 0.5–4. The 3D volume zoom spans 0.5–3.</p><p>Rotation advances yaw by 0.06 rad/s and pauses during pointer gestures, in Documentation and when the page is hidden. Reduced-motion preferences disable automatic rotation at startup; the user can opt in with the checkbox. An edge-on slice cannot be picked reliably; Shift-drag to tilt it.</p>','Color science')

n=100;c0='#1464e8';c1='#ffbd32';q0=lab(c0);q1=lab(c1);r0=[decode(int(c0[i:i+2],16)/255) for i in (1,3,5)];r1=[decode(int(c1[i:i+2],16)/255) for i in (1,3,5)]
oks=[hexlin(linear(*[a+(b-a)*i/(n-1) for a,b in zip(q0,q1)])) for i in range(n)]
rgb=[hexlin([a+(b-a)*i/(n-1) for a,b in zip(r0,r1)]) for i in range(n)]
bands=[c0]*(n-1)+[c1]
ramps=''
for y,name,colors in [(42,'Smooth · OKLab',oks),(119,'Linear-light RGB',rgb),(196,'Bands · previous key',bands)]:
    ramps+=txt(28,y,name,font_size=12)+ramp(colors,28,y+12,664,30)
ramps+=txt(28,279,c0)+txt(692,279,c1,text_anchor='end')
rampfig=fig('Comparison of OKLab interpolation, linear RGB interpolation and held bands',ramps,'The same blue and yellow endpoints produce different intermediate colors. Samples use the app’s OKLab and sRGB equations. Bands holds the first color until the second key.',302)
topic('interpolation','Gradient keys and interpolation','Color keys tell the gradient which colors to pass through. Alpha keys control opacity independently. Smooth blends between keys; Bands keeps each value unchanged until the next key.', '<h2>Key model</h2><p>Each layer supports 2–16 color keys and 2–16 alpha keys. Color keys contain <code>{t, hex}</code>; alpha keys contain <code>{t, a}</code>. Both sets are sorted by position for evaluation. Position is displayed as <code>100t%</code>. Color numbers are their order from the bright/right end, not permanent identities.</p><p>Drag a marker or use Position to move a key. Each drag is one Undo/Redo action. Clicking empty ramp space adds a color key; + and − also manage color keys. Alpha markers, alpha-value controls and alpha-key creation are not exposed in this workspace. Color edits do not modify existing opacity keys. Saved snapshots retain opacity data and restore it when loaded; exporting leaves the authored opacity unchanged. Exports retain stored ramp opacity automatically. New default ramps are opaque. Delete opens a confirmation with Delete focused: Enter confirms; Escape cancels. At least two keys remain. Distinct positions give predictable smooth segments; coincident positions can create abrupt edges.</p><h2>Smooth interpolation</h2><pre>w = (t − t₀) / (t₁ − t₀)\nq(t) = (1 − w) OKLab(HEX₀) + w OKLab(HEX₁)\nRGB_linear(t) = clamp(OKLab_to_linear_sRGB(q(t)), 0, 1)\nα(t) = (1 − wα) α₀ + wα α₁   using the separate alpha segment</pre><p>Sampling before the first key or after the last returns its endpoint value. Color interpolation happens in OKLab, whereas alpha interpolates directly. Display RGB is encoded to sRGB and quantized when written to the canvas or PNG.</p>'+rampfig+'<h2>Bands</h2><p>Bands returns the previous key’s color and alpha throughout each segment, switching at the next key. Texture filtering can soften these boundaries in an engine. Use point filtering when exact steps matter.</p><h2>Export interpolation</h2><p>The export dialog defaults to <strong>Perceptual (OKLab)</strong>, which follows the editor’s Smooth calculation. Unity C# uses <code>GradientMode.PerceptualBlend</code> and <code>ColorSpace.Linear</code> for the decoded linear RGB keys. <strong>Linear RGB</strong> instead blends decoded RGB channels and can change intermediate colors. This choice changes the exported PNG or key-data instructions, not the editor.</p><pre>Linear RGB export:\nRGB(t) = (1 − w) decode_sRGB(HEX₀) + w decode_sRGB(HEX₁)</pre><p>Both modes keep the separate alpha interpolation. Bands stays constant regardless of the Smooth export choice. For Unreal, OKLab JSON requires a custom evaluator or a perceptually sampled PNG. Read the '+link('engine-integration','engine integration guide')+' for version requirements and texture precision limits.</p>','Gradient design')

layers='<rect x="35" y="36" width="650" height="34" fill="#cc814b"/>'+txt(44,59,'Importance 01 · upper scalar range',fill='#142033')+'<rect x="35" y="90" width="650" height="34" fill="#4678b7"/>'+txt(44,113,'Importance 02 · lower scalar range')
layers+='<path d="M35 222L35 166H360C400 166 410 202 455 202H685V222Z" fill="#4678b7" opacity=".8"/><path d="M35 222V202H360C400 202 410 166 455 166H685V222Z" fill="#cc814b" opacity=".8"/>'+txt(35,248,'t = 0')+txt(390,248,'split s',text_anchor='middle')+txt(685,248,'t = 1',text_anchor='end')
layerfig=fig('Two importance ramps and a soft split transition',layers,'Conceptual layer weights around the split. Actual output also depends on each ramp’s alpha, remapped sample coordinate and the source image alpha.',270)
topic('importance-layers','Preview layers and importance','Build the Preview from images with independent Gradient Maps. Select an image to edit its active Gradient Map, and use the stack to control visibility, order, opacity and blending.', OUT.joinpath('preview-layers-documentation.html').read_text()+'<h2>Importance ramp identity</h2>'+layerfig+'<p>Importance 01 covers the upper part of the combined scalar range; Importance 02 covers the lower part. They have independent color keys, alpha keys, preset selection and transition mode. Internal identifiers <code>emission</code> and <code>smoke</code> are historical names, not physical simulation outputs.</p><p>The workspace edits the selected image’s active importance ramp. Applying a library preset changes that ramp only; Random generates both. The legacy importance switch and mapping selector are hidden. Stored maps and Preview presets retain these settings: active uses the full scalar range without split remapping; combined remaps both ramps; individual importance views isolate one contribution.</p><h2>Combined mapping</h2><pre>t = normalized source signal, s = split (0.15…0.90; initial Reference 0.72)\nt₁ = clamp((t − s) / (1 − s), 0, 1)\nt₂ = clamp(t / s, 0, 1)\nu  = clamp((t − s + 0.10) / 0.20, 0, 1)\nm  = u²(3 − 2u)\n\nw₁ = m α₁(t₁)          w₂ = (1 − m) α₂(t₂)\nA = w₁ + w₂\nC_linear = (w₁ C₁(t₁) + w₂ C₂(t₂)) / A   when A &gt; 0\nOutput alpha = A × source alpha</pre><p>A zero combined alpha produces a transparent result. The transition spans 0.20 of the normalized signal around the split. Mixing uses linear-light RGB weighted by alpha. It is a normalized layer blend, not front-to-back volumetric compositing.</p><p>The combined appearance is not baked into the two-row PNG: export contains the two original ramps. Reproduce this split logic in your material if you want the combined behavior.</p>','Gradient design')

topic('palettes','Palette library and favorites','Presets provide starting points for effects, materials and visual experiments. Search for a name or theme, then adjust the result to fit your own effect. Favorites keep frequently used ramps close at hand.', '<h2>What a preset changes</h2><p>The bundled library contains 1086 presets in this version. Presets define a ramp’s colors and positions, and can include a designed transition. Selecting one applies it to the active importance layer. The star button adds or removes its stable preset identifier from favorites.</p><p>Search includes preset names, aliases, categories and descriptive text. Matching folders open during search. The seven groups are Effects, Nature &amp; materials, Color studies, Data &amp; diagnostics, Art studies, Design studies and Color &amp; experiments. Environment and surface palettes belong with materials.</p><h2>Browsing folders</h2><p>The seven categories contain 48 theme folders, each holding 8–45 presets in this version. Related small folders share a family; broad folders split by use. Effects are grouped into fire, atmosphere, water, electricity, organic effects, space, graphic motion, impacts, transitions and states. Art uses eight movement families, and design uses four. Nature separates environments, surfaces, stone, foliage, flowers, birds and insects, and land and marine life. Data groups sequential measurements, differences, cycles and diagnostics. Color studies separate warm, cool and mixed accents; experiments separate illustration, print, animation, optics, light, hue, value and chroma.</p><p>These are browsing choices, not scientific classifications. Search recognizes both the current folder labels and the previous themes and movement names. Each bundled preset appears once in its category; favorites and My palettes remain separate. Reorganization does not merge ramps or change colors, key positions, identifiers or saved palettes.</p><h2>Interpretation</h2><p>Bundled names, search tags and descriptions use visual terms for color, light, surfaces and environments. Religious themes and references to fictional characters, franchises or commercial brands are replaced with neutral wording. This editorial choice is not trademark clearance. Historical internal identifiers remain stable for saved selections and favorites; user-authored names are preserved. A material or scientific label does not establish an official palette or a measured spectral dataset. Approximate black-body colors are useful design references, not a calibrated temperature measurement of the preview.</p><p>Presets and random generation serve different purposes: presets reproduce authored choices; Random creates new candidates. Both still pass through the app’s sRGB storage, gamut and interpolation behavior.</p>','Gradient design')

topic('random','Random generation and harmony','Random creates fresh ramp pairs. ColorPlay adapts to the image and compares color contexts; other modes explore harmony, independent RGB or evenly sampled OKLab paths.', '<h2>Generation modes</h2>'+table(['Mode','Construction'],[['Graphic Design','15 harmonic/design families; fixed points and ordered value. Random applies Bands; other modes apply Smooth.'],['ColorPlay','Albers-inspired contextual exploration: image-weighted hue groups, spatial contrast and chroma-area evaluation on two backgrounds.'],['Harmonic','Chooses among monochromatic, analogous, complementary, split, triadic and tetradic relationships; evaluates candidate ramps.'],['Free','Independent random 8-bit RGB colors; no guaranteed lightness progression or harmonious relationship.'],['Perceptual','Builds a dense OKLab path and samples approximately equal accumulated color distances.'],['Monochromatic / Analogous','Hue offsets [0°] / [−25°, 0°, 25°].'],['Complementary / Split','Hue offsets [0°, 180°] / [0°, 150°, 210°].'],['Triadic / Tetradic','Hue offsets [0°, 120°, 240°] / [0°, 90°, 180°, 270°].'],['Warm / Cool','Warm starts near 25°–45° with offsets [0°, 25°, 55°]; Cool near 190°–215° with [0°, 30°, 65°].']])+'<h2>Perceptual sampling</h2><pre>d(q₀, q₁) = √[(ΔL_UI / 100)² + (Δa_UI / 250)² + (Δb_UI / 250)²]\nDᵢ = Σ d(qⱼ₋₁, qⱼ) along a 257-sample path\nChoose colors at approximately equal intervals in accumulated D.</pre><p>This is OKLab Euclidean distance, not a guaranteed just-noticeable difference. Gamut fitting, display conditions and the sampled path affect the result. Harmony angles use the app’s OKLab hue plane, not a painter’s RYB wheel. A 180° hue offset is a design relationship; it is not proof of an additive-light complement, sufficient contrast or distinguishability for every viewer.</p><h2>Changes to your ramp</h2><p>Random updates both ON ramps, preserving counts/alpha and selecting Smooth. It draws once at the end; ColorPlay reuses repeated color conversions. Selection is independent; all OFF changes nothing. Guided modes use 32×32 scene estimates: Add is 10%; others rank 60/30/10. Named harmonies share one hue family across ON images and keep their angles. Dominant is quieter; accent chroma follows a reference ramp. Saturation/chroma varies ±25%, within gamut. OFF stays fixed. Estimates guide colors, not area quotas; hover rows for details. Temp_Design adds one Normal image with five grayscale keys. It is seeded once; edits/deletion persist. Loads finish quietly; errors remain visible. The preset menu starts on Default: Explosion_Emissive (Add), Explosion_Smoke and BG, top to bottom. Images embedded. Cleanup keeps Default and Temp_Design; later presets remain. Free uses raw independent RGB, without role, luma or Add constraints. Guided Random preserves each point’s linear Rec.709 luminance after hue/chroma edits; Add’s lowest point stays black. Luma restoration overrides brightness variation and source floors. Graphic Design keeps points fixed with ordered value (L 12–20 to 90–96), varied chroma and Bands on Random only. 15 harmonic/design recipes guide 60/30/10 hue families; spacing controls widths. Alpha is fixed. Add layers use the 10% accent hue, with a black base and quiet next point. Other modes keep logic. Other guided modes keep fresh hues and role chroma floors with ±25% variation. Gamut fitting can lower chroma; roles are not pixel quotas.</p>'+OUT.joinpath('colorplay-documentation.html').read_text(),'Gradient design')

reference='file:///Users/raffribeiro/Documents/Codex/2026-10-01/referenced-chatgpt-conversation-this-is-an/outputs/default-explosion.webp'
topic('grayscale-mapping','Reference image and scalar mapping','Image brightness selects the gradient coordinate. Source alpha is preserved while colors follow the ramp.', '<h2>Normalize values</h2><p>Normalize values is a per-layer toggle, off by default. It stretches visible min/max to 0–255; off restores source values. Selection shows each layer’s state, retained by Undo/Redo, browser restore and presets. Alpha and keys are preserved. Full-range, flat and transparent sources are unchanged.</p><pre>v_new = round[255 (v − v_min) / (v_max − v_min)]</pre><h2>The reference asset</h2><figure><img src="'+reference+'" alt="Original explosion reference asset used by the preview before gradient recoloring" width="512" height="512" loading="lazy"><figcaption>Reference at 512 × 512; ramps recolor its grayscale signal.</figcaption></figure><p>The 1024 × 1024 reference is resampled to 512 × 512. Its checkerboard is opaque content; source alpha is retained.</p><h2>Signal construction</h2><p>The bundled Reference stretches weighted encoded bytes. Imported images retain their range unless Normalize values is on.</p><pre>g = 0.2126 R_byte + 0.7152 G_byte + 0.0722 B_byte\nv = round[255 (g − g_min) / (g_max − g_min)]\nt = v / 255\nOutput = gradient lookup at t\nOutput alpha = gradient alpha × source alpha</pre><p>The Reference uses divisor one for a zero range. A 256-entry LUT maps encoded brightness, not physical linear-light luminance.</p><h2>Brightness versus linear luminance</h2><p>Relative luminance decodes channels before weighting:</p><pre>Y_linear = 0.2126 decode_sRGB(R)\n         + 0.7152 decode_sRGB(G)\n         + 0.0722 decode_sRGB(B)</pre><p>RGB channels here are normalized. Bloom and attention use linear luminance.</p><h2>What to infer from the preview</h2><p>Source values determine the 2D result.</p><p>Filter order is <strong>gradient mapping → image compositing → bloom → color-vision filter → attention overlay</strong>. These filters affect the preview only.</p>','Preview analysis')

topic('bloom','Post-process bloom','Bloom adds a soft glow around bright areas of the reference preview. It helps you inspect a glowing effect, but it does not change the gradient texture you export.', '<h2>Highlight selection</h2><p>The filter uses linear-light luminance with a soft threshold. It creates a highlight image by reducing alpha according to the highlight weight.</p><pre>Y = 0.2126 R_linear + 0.7152 G_linear + 0.0722 B_linear\nτ = 0.45, κ = 0.15\nz = clamp(Y − τ + κ, 0, 2κ)\nh = min(1, max(Y − τ, z² / (4κ)) / max(Y, 10⁻⁶))\nHighlight alpha = source alpha × h</pre><h2>Blur and blend</h2><p>Two Canvas 2D blur passes use radii of 10 px and 3 px at the 512-pixel reference resolution. They are screen-blended with strengths B and 0.7B, where the UI’s 100% corresponds to B = 1. The supported amount is 0–200%; strengths above one use repeated blend passes.</p><p>This is a display-range preview effect, not an HDR renderer or a simulation of scattering. The PNG stores 8-bit gradient colors and alpha; it contains neither bloom nor exposure values. An engine’s bloom, tone mapping and exposure can produce a different result.</p>','Preview analysis')

topic('color-vision','Color-vision simulation','The vision menu shows approximate ways an effect can appear with different color-vision deficiencies. Use it to check whether meaningful structure remains visible when some color distinctions are reduced.', '<h2>Available modes</h2><p>Regular Vision leaves the mapped preview unchanged. Protanopia, deuteranopia and tritanopia use full-deficiency matrices; protanomaly, deuteranomaly and tritanomaly use the corresponding severity-0.5 matrices. Grayscale removes chromatic information using linear-light luminance.</p><pre>RGB_linear = decode_sRGB(RGB_encoded)\nRGB_simulated = clamp(M_mode × RGB_linear, 0, 1)\nRGB_display = encode_sRGB(RGB_simulated)\nAlpha remains unchanged.</pre><p>The matrices follow the model of Machado, Oliveira and Fernandes (2009). The anomaly modes use precomputed intermediate matrices, not a 50% blend with the unchanged image. Tritan simulations are also approximations and should be interpreted with care.</p><h2>Practical use</h2><p>Compare silhouettes, contrast and transitions across modes. Do not depend on hue alone to communicate an important category. Simulation is not a diagnosis, an exact prediction for every observer or proof of accessibility. Filters run after preview bloom and do not alter saved keys or PNG export.</p><p>Model source: '+ref('https://www.inf.ufrgs.br/~oliveira/pubs_files/CVD_Simulation/CVD_Simulation.html','Machado–Oliveira–Fernandes color-vision model')+'.</p>'+ '<h2>Compare Regular Vision and the filter</h2><p>Every mode other than Regular Vision opens a split comparison centered at 50%. The left side uses the current mapped gradient and bloom with Regular Vision; the right side uses the selected vision filter. Drag the middle handle horizontally, or focus it and use the range control keyboard keys. At 0% the full filtered image is visible; at 100% the full regular image is visible. Changing the vision mode resets the divider to the center. Palette and bloom edits retain its current position.</p><p>Both canvases share the same size and transparency. Complementary clipping avoids double-compositing alpha. Divider movement only changes the displayed split; it does not recalculate the filter, alter the ramp, or enter export. Regular Vision hides the comparison control. Attention, when enabled, is calculated on the full filtered image and visible in the filtered portion.</p>','Preview analysis')

topic('attention','Attention overlay','Enable the eye toggle to compare up to three distinct areas that stand out in the preview. Numbered eyes show Primary, Secondary and Tertiary visual saliency, using color, brightness and edge contrast rather than brightness alone.', OUT.joinpath('attention-documentation.html').read_text()+'<figure><img src="'+OUT.joinpath('attention-reference-study.png').resolve().as_uri()+'" alt="Original saliency study comparing a mapped fire ramp with its three ranked visual foci" width="1048" height="560" loading="lazy"><figcaption>Standalone calculation study: the reference mapped with a Smooth fire palette, without bloom or a vision filter. Eyes come from the current algorithm. This is not a browser screenshot or a human-gaze validation.</figcaption></figure>','Preview analysis')

# PNG layout diagram: exact row order and sampling centers.
exportfig=fig('Two-layer PNG layout and normalized row-center texture coordinates',txt(28,29,'One image · width W · total height 2H')+ramp(oks,28,48,664,56)+ramp(list(reversed(oks)),28,104,664,56)+'<rect x="38" y="61" width="220" height="28" rx="3" fill="#111c29" opacity=".92"/>'+txt(45,82,'Importance 01 · v = 0.25',fill='#fff')+'<rect x="38" y="118" width="220" height="28" rx="3" fill="#111c29" opacity=".92"/>'+txt(45,139,'Importance 02 · v = 0.75',fill='#fff')+txt(28,193,'First texel: t = 0')+txt(692,193,'Last texel: t = 1',text_anchor='end')+txt(28,221,'Row coordinates shown with a top-left image origin.',font_size=12),'Illustrative ramps show the row order, not your current palette. Each layer repeats its horizontal ramp across H identical rows.',244)
topic('png-export', 'Export options and PNG', 'Choose how the ramp should blend before exporting it. The shared dialog offers a PNG texture, Unity C# or Unreal JSON, with one or both layers and optional transparency. PNG adds texture size and file-name controls.', '<h2>A shared export dialog</h2><p>Export PNG opens the dialog with PNG selected. Choose PNG texture, Unity C# or Unreal JSON in Format before confirming. There is no separate code-copy button or workspace Engine selector. The dialog preview shows the chosen export interpolation; the editor keeps its original Smooth or Bands setting.</p><h2>Options</h2><div class="atlas-docs-table"><table><thead><tr><th scope="col">Option</th><th scope="col">Behavior</th></tr></thead><tbody><tr><td>Format</td><td>PNG texture, Unity C# or Unreal JSON. Code is copied after review; PNG is downloaded.</td></tr><tr><td>Layers</td><td>Active layer, or both. PNG places Importance 01 above Importance 02. Key data exports two separate gradients in that order.</td></tr><tr><td>Smooth interpolation</td><td>Perceptual (OKLab), the default, follows the editor. Linear RGB blends decoded channels for compatibility and changes intermediate Smooth colors. Bands keeps its steps in either choice.</td></tr><tr><td>Width / Height per layer</td><td>PNG only: integer width 1–4096, height 1–1024. Defaults 256 × 16. Exports use the active ramp.</td></tr><tr><td>Alpha</td><td>Authored ramp alpha is retained in the PNG or copied data, without background compositing.</td></tr><tr><td>File name</td><td>PNG only: sanitized base name with .png appended. Path separators and invalid characters are removed.</td></tr></tbody></table></div><h2>Sampling and encoding</h2><pre>For output column x = 0…W−1:\nt = x / (W−1)      when W &gt; 1\nt = 0              when W = 1\n\nEvaluate RGB using the selected Smooth export interpolation.\nBands uses the previous key in each segment.\nRGB bytes = round(255 × encode_sRGB(clamped linear ramp color))\nAlpha byte = round(255 × ramp alpha)   or 255 when opaque\nRepeat the same row H times per layer.</pre><p>The PNG is 8-bit RGBA, with encoded sRGB color channels and a linear opacity channel. Canvas encoding can discard RGB at zero alpha and introduce rounding at low alpha; use opaque export when preserving RGB independently of opacity is essential. A wider texture samples the gradient more densely; it does not add authored keys or HDR precision. The file contains the ramps, without source-image alpha, combined-layer mapping, bloom, vision simulation or attention overlays.</p><h2>Confirming an export</h2><p>Download PNG creates a PNG blob and starts a browser download. Copy Unity C# or Copy JSON sends the generated text to the clipboard flow. Cancel, the close button, Escape or the backdrop dismisses the dialog and restores focus to its opening button. Closing during PNG encoding cancels that download, including if you reopen the dialog.</p><p>The host must allow downloads or clipboard access. A successful click alone does not prove that a file was saved. For target setup, see <a href="#doc-engine-integration" data-doc-link="engine-integration">Engine integration</a>; for missing files, see <a href="#doc-troubleshooting" data-doc-link="troubleshooting">Troubleshooting</a>.</p>'+exportfig, 'Export and integration')

topic('engine-integration', 'Engine integration', 'Use a PNG as a color lookup texture, or copy key data to build an engine gradient. Choose Perceptual to follow the editor’s smooth color path, or Linear RGB when your target needs ordinary channel blending. Test the result with the engine’s actual display settings.', '<h2>Choose interpolation deliberately</h2><p>Perceptual (OKLab) follows the editor’s Smooth model. Linear RGB is a compatibility choice that changes colors between keys. Both export decoded <code>linear-sRGB</code> key values; interpolation determines what happens between those values. Bands always uses constant steps. Export preferences do not alter the authored ramps.</p><h2>Unity C#</h2><p>For Unity 6, the perceptual export uses the native OKLab mode and explicitly declares the color space of its keys:</p><pre>var gradient = new Gradient();\ngradient.mode = GradientMode.PerceptualBlend;\ngradient.colorSpace = ColorSpace.Linear;\n// SetKeys receives decoded linear-sRGB color keys and opacity keys.</pre><p>A Gradient created in C# defaults to Gamma for this property. Because Color Atlas supplies decoded linear RGB, leaving that default would describe the input incorrectly. Unity uses <code>colorSpace</code> for PerceptualBlend. See the official <a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/GradientMode.PerceptualBlend.html" target="_blank" rel="noopener noreferrer">PerceptualBlend reference</a> and <a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Gradient-colorSpace.html" target="_blank" rel="noopener noreferrer">Gradient.colorSpace reference</a>.</p><p>Linear RGB exports <code>GradientMode.Blend</code>; Bands exports <code>GradientMode.Fixed</code>. If your Unity version lacks PerceptualBlend or the colorSpace property, choose Linear RGB, or use a perceptually sampled PNG or custom OKLab evaluator. Native code is supplied when every selected layer has at most 8 color and 8 alpha keys. If any selected layer exceeds this limit, the whole export falls back to JSON without dropping keys. Both layers produces separate <code>importance01</code> and <code>importance02</code> Gradients.</p><h2>Unreal JSON and key-data fallback</h2><p>Unreal export is descriptive JSON, not a .uasset or automatic importer. Single-layer JSON contains colorSpace, interpolation, colors and alphas. Two-layer JSON contains a layers array with each layer’s identity and its own interpolation. Metadata distinguishes <code>oklab</code>, <code>linear</code> and <code>constant</code>.</p><p>An ordinary linear RGB CurveLinearColor does not reproduce an OKLab ramp between sparse keys. Use a custom OKLab evaluator or the perceptual PNG, or choose Linear RGB and build the corresponding native curve. Preserve every key in the Unity JSON fallback as well. The exportHint explains the target limitation; JSON metadata alone does not implement an evaluator.</p><h2>Texture setup</h2><ol><li>Import PNG as a color texture. Enable sRGB decoding for RGB, or perform that decode exactly once in your shader. Alpha remains opacity.</li><li>Use clamp addressing. Disable mipmaps when they would mix layers or smooth intentional bands.</li><li>Use point filtering for exact Bands. Bilinear filtering is usually useful for Smooth, but interpolates between sampled texels in the engine.</li><li>Choose the correct layer row and test endpoint colors. Engine UV conventions can flip vertical order.</li><li>Apply the target engine’s blend, exposure and bloom settings to the resulting color.</li></ol><h2>Sampling coordinates</h2><pre>Given normalized signal t, texture width W:\nu = (t(W−1) + 0.5) / W\n\nSingle layer: v = 0.5\nTwo layers, top-left image convention:\n  Importance 01: v = 0.25\n  Importance 02: v = 0.75\n\nRGBA = texture sample at (u, v)</pre><p>The horizontal formula samples endpoint texel centers. Verify the vertical origin in the engine. Two-layer export does not include the combined split formula; implement <a href="#doc-importance-layers" data-doc-link="importance-layers">importance mapping</a> in the material if needed.</p><h2>Matching the preview</h2><p>Perceptual export matches the editor’s interpolation model, not a guarantee of pixel-identical engine output. C# values are rounded to six decimals; PNG quantizes RGB and alpha to 8 bits, and bilinear filtering only approximates the sampled curve. Compression, tone mapping, exposure, color management, the source scalar and alpha blending can also change the result. Use lossless texture settings when exact channel values matter. Color Atlas bloom and analysis filters are not exported.</p><p>Further references: <a href="https://docs.unity3d.com/ScriptReference/Gradient.SetKeys.html" target="_blank" rel="noopener noreferrer">Unity Gradient key limits</a>, <a href="https://docs.unity3d.com/Manual/linear-textures.html" target="_blank" rel="noopener noreferrer">Unity sRGB texture decoding</a>, and <a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/curve-atlases-in-unreal-engine-materials" target="_blank" rel="noopener noreferrer">Unreal Curve Atlases</a>.</p>', 'Export and integration')

topic('state','State, persistence and accessibility','Your edits remain available while you move between Editor and Documentation. Whether they survive reopening depends on the host that runs the app, so export important work before closing the page.', '<h2>State model</h2><p>The editor keeps the selected layer, color and alpha keys, presets, favorites, preview settings and color controls and user-palette snapshots in a validated state object. My palettes shares this persistence provider; see '+link('interface','My palettes')+' for save, load, deletion and capacity rules. The standalone export attempts localStorage persistence scoped to the page path and query string. If browser storage is unavailable, it falls back to session memory. Host persistence uses <code>window.openai.widgetState</code> and <code>setWidgetState</code> when available. A standalone page without a persistence provider should not be assumed to restore edits after reload.</p><p>Invalid restored values are constrained to supported ranges; key arrays require valid positions, HEX values and alpha, and are capped at 16 keys. Layer and random defaults have version markers to support migration. The workspace always opens in VFX, including when restoring an older selected system. Retained Munsell and experimental OKLab/OKLCh data are preserved, while their modes stay hidden. Documentation navigation does not rewrite the editor state.</p><h2>Interaction and motion</h2><p>Sliders, selects, HEX Apply and key buttons provide ordinary form controls alongside the visual tools. Focusable dividers support keyboard resizing. Documentation uses labeled search, native buttons, heading focus when changing a topic and a live result count. Images and diagrams have descriptions.</p><p>The logo animates on entry. Color markers stay still during pointer edits and pulse once on release. Reduced-motion preferences suppress automatic entry motion and disable initial volume rotation. Pointer gestures batch visual updates with immediate wheel selection and continuous 3D marker dragging.</p><h2>Local operation</h2><p>The exported page includes its code, palette data and reference asset. Core editing does not require an account or a remote rendering service. Links to external reference manuals require connectivity. Clipboard and download permissions remain controlled by the embedding browser or host. Copy feedback reports the browser acknowledgement; if automatic copying fails, a visible manual-copy dialog selects the text. See '+link('interface','Copy HEX and clipboard feedback')+' for exact behavior.</p>','Reference')

topic('troubleshooting','Troubleshooting','Most differences come from the selected layer, the signal being mapped or the settings used to display a texture. Check those before changing the colors themselves.', '<h2>Common issues</h2>'+table(['Symptom','Check'],[['A saved palette is missing','Open My palettes and clear search. Reopen the same file path and query string. Session-only save feedback means storage failed; browser data clearing can also remove local work.'],['My palettes is full','The collection has an 8 KiB storage budget. Export key data for important entries before deleting an unused snapshot.'],['Where is Copy gradient data?','Open Export PNG and select Unity C# or Unreal JSON in Format. The submit button then copies the reviewed data.'],['Copy HEX does not paste','Look for Copied followed by the exact HEX, then paste to confirm. If automatic copying fails, use the selected text in Copy manually with ⌘C / Ctrl+C. See Workspace and controls for acknowledgement limits.'],['Download PNG does nothing','Confirm dimensions are valid, the host allows downloads, and the browser has not blocked the file. Check its Downloads location. The button exports a gradient, not the effect screenshot.'],['PNG looks different in the engine','Decode sRGB exactly once; check compression, tone mapping, filtering and alpha blending. Check export interpolation: Linear RGB differs from the editor; perceptual Unity code needs PerceptualBlend and ColorSpace.Linear. Unreal OKLab data needs a custom evaluator or PNG.'],['Two layers appear reversed','Check texture v origin and sample the correct row center. Test distinctive colors in the two rows.'],['A very saturated color shifts','It may lie outside sRGB. Gamut fitting lowers chroma; unlocked HEX output still clips.'],['Wheel changes do nothing','Select a color key rather than an alpha key. Click inside the pick disk; the hue ring is a visual reference.'],['3D picking fails at an angle','Shift-drag to tilt the slice away from an edge-on view. Drag the selection circle to edit color; other left drags rotate.'],['Smooth looks stepped','Check that Bands is not selected. Use a wider PNG and appropriate filtering; 8-bit output still has finite precision.'],['Bright colors dominate the reference','The source is a normalized grayscale image. Review key positions, alpha, combined-layer split and bloom separately.'],['A preset changed only one ramp','Presets apply to the active layer. Switch layers to edit the other. Random updates both.'],['Edits disappear after reload','Host persistence may be unavailable. Export a PNG and copy the key data before closing.']])+'<h2>Useful comparison procedure</h2><p>Set Regular Vision, turn off the eye overlay, reduce bloom to zero and inspect Selected gradient. Export a Perceptual PNG and compare those same unfiltered colors. A Linear RGB export deliberately changes intermediate Smooth colors. Then enable the combined preview and each filter separately to identify which step changes the appearance.</p>','Reference')

topic('glossary','Glossary and source bibliography','These terms distinguish stored colors, the scalar signal that selects them and the effects applied only for preview. Keeping those roles separate makes exporting and debugging easier.', '<h2>Glossary</h2>'+table(['Term','Meaning in Color Atlas'],[['Scalar / t','Normalized input that selects a location on the ramp.'],['Key','A color or alpha value at a normalized position.'],['sRGB','Display color encoding used by HEX and PNG RGB channels.'],['Linear sRGB','Decoded RGB used for light calculations and layer mixing.'],['OKLab / OKLCh','Perceptual coordinates used for authoring and Smooth interpolation; cylindrical coordinates describe the same space.'],['Gamut','Colors representable by the chosen display RGB space.'],['Chroma','Distance from neutral in the a/b color plane.'],['Relative chroma / Saturation','The app’s chroma relative to a fitted reference at the same lightness and hue; not a universal saturation definition.'],['Export interpolation','OKLab for perceptual Smooth, linear RGB for compatible Smooth, constant for Bands.'],['Importance layer','One of two editable ramps with a role in the combined scalar mapping.'],['LUT','Lookup table: a sampled mapping from scalar to RGBA.'],['Straight alpha','RGB values with a separate opacity channel; the export does not intentionally multiply RGB by opacity.'],['Bloom','A blurred highlight contribution in the preview.'],['Color-vision simulation','An approximate linear RGB transform for preview inspection.'],['Attention overlay','An app-specific brightness and local-contrast heatmap.']])+'<h2>Primary technical references</h2><ul><li>'+ref('https://bottosson.github.io/posts/oklab/','Björn Ottosson — OKLab definition and matrices')+'.</li><li>'+ref('https://www.w3.org/TR/css-color-4/#color-conversion-code','W3C CSS Color 4 — color conversion algorithms')+'.</li><li>'+ref('https://www.inf.ufrgs.br/~oliveira/pubs_files/CVD_Simulation/CVD_Simulation.html','Machado, Oliveira and Fernandes — color-vision deficiency model')+'.</li><li>'+ref('https://www.rit.edu/science/munsell-color-lab','RIT — Munsell Color Science Laboratory')+'.</li><li>'+ref('https://docs.unity3d.com/6000.0/Documentation/ScriptReference/GradientMode.PerceptualBlend.html','Unity — PerceptualBlend')+' and '+ref('https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Gradient-colorSpace.html','Gradient.colorSpace')+'.</li><li>'+ref('https://colour.readthedocs.io/en/master/generated/colour.MUNSELL_COLOURS.html','Colour — Munsell renotation data and 0.975 luminance convention')+'.</li><li>'+ref('https://docs.unity3d.com/ScriptReference/Gradient.SetKeys.html','Unity — Gradient.SetKeys')+' and '+ref('https://docs.unity3d.com/Manual/linear-textures.html','working with linear textures')+'.</li><li>'+ref('https://dev.epicgames.com/documentation/en-us/unreal-engine/curve-atlases-in-unreal-engine-materials','Epic Games — Curve Atlases in Unreal Engine Materials')+'.</li></ul><h2>Guide design</h2><p>This original guide uses task-based chapters, searchable navigation and illustrated technical references, inspired by manuals such as '+ref('https://docs.jangafx.com/embergen/','EmberGen documentation')+'. The diagrams are original demonstrations of Color Atlas calculations; they are not screenshots or documentation copied from another product.</p><p>Implementation-specific numbers and formulas were checked against the app’s current source. They describe the present editor, not every feature of the referenced color models or engines.</p>','Reference')

nav=''
last=None
for key,title,group,_ in chapters:
    if group!=last:nav+='<h2>'+escape(group)+'</h2>';last=group
    nav+=f'<a href="#doc-{key}" data-doc-link="{key}">{escape(title)}</a>'
html='<section id="atlas-documentation" class="atlas-docs" aria-label="Color Atlas documentation" lang="en" hidden><aside class="atlas-docs-sidebar"><p class="atlas-docs-eyebrow">Documentation</p><label class="atlas-docs-search-label" for="atlas-doc-search">Search the guide</label><input id="atlas-doc-search" type="search" placeholder="Search topics, controls, formulas…" autocomplete="off"><p id="atlas-doc-results" role="status" aria-live="polite"></p><nav aria-label="Documentation chapters">'+nav+'</nav></aside><div class="atlas-docs-reading"><p id="atlas-doc-empty" class="doc-note" hidden>No matching topics. Try a control name such as Saturation, a color space such as OKLab, or clear the search.</p>'+''.join(c[3] for c in chapters)+'<nav class="atlas-docs-pagination" aria-label="Adjacent documentation topics"><button type="button" data-doc-previous>← Previous topic</button><button type="button" data-doc-next>Next topic →</button></nav></div></section>'
(OUT/'atlas-documentation.html').write_text(html)
source_markdown=['# Color Atlas — source bibliography', '', 'Sources cited or cross-checked for the English guide. Bibliographic identities checked on '+source_catalog['checked_on']+'.', '', 'Each entry states its role; inclusion is not a claim that every feature comes from a journal paper or that all full texts are freely accessible.', '']
for kind in dict.fromkeys(source['kind'] for source in sources):
    source_markdown+=['## '+kind,'']
    for source in sources:
        if source['kind']!=kind:continue
        source_markdown+=['### '+source['title'],'',source['author']+' — '+source['year']+'.','',source['used_for'],'']
        source_markdown+=['- ['+item['label']+']('+item['url']+')' for item in source['links']]
        source_markdown+=['','Guide topics: '+', '.join(source['topics'])+'.','']
source_markdown+=['## App-specific implementation and original material','','Coordinate scaling, relative chroma, gamut interaction rules, harmony, importance mapping, reference-image normalization, bloom parameters and attention are described from the app’s own implementation. The seven guide diagrams are original calculations and a contextual color exercise. The explosion is a bundled project reference asset whose external authorship remains unverified. Presets are design references, without an inferred measured or official provenance.','','Local implementation references:','', '- [Canonical app source](/Users/raffribeiro/.codex/visualizations/2026/10/01/01a0f83c-7569-7dd0-ad8b-3e73b2b454df/munsell-selector.html)', '- [Munsell data generator]('+str((OUT/'munsell_data.py').resolve())+')', '- [Export evaluator and options]('+str((OUT/'atlas-png-export.js').resolve())+')', '- [My palettes implementation]('+str((OUT/'atlas-user-palettes.js').resolve())+')', '- [Documentation source catalogue]('+str((OUT/'documentation-sources.json').resolve())+')','']
(OUT.parent/'outputs'/'color-atlas-sources.md').write_text('\n'.join(source_markdown))
# Independent numerical sanity checks for diagrams.
assert abs(decode(.5)-.21404114048223255)<1e-12
assert max(abs(a-b) for a,b in zip(lab('#ffffff'),[1,0,0]))<1e-7
assert oks[0]==c0 and oks[-1]==c1
assert rgb[0]==c0 and rgb[-1]==c1
print(f'Created {len(chapters)} English documentation topics, 7 original illustrations; {len(html.encode())} bytes.')
